<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Communications - C-Net Library</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1250px;margin:28px auto;padding:0 18px}.top,.inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:18px}.grid{display:grid;grid-template-columns:380px 1fr;gap:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;margin-bottom:18px}.field{margin-bottom:10px}input,select,textarea{width:100%;padding:9px;border:1px solid #d1d5db;border-radius:8px;margin-top:4px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#111827;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.alt{background:#0f766e}.danger{background:#b91c1c}.muted{color:#6b7280;font-size:12px}.template{border:1px solid #e5e7eb;border-radius:12px;padding:14px;margin-bottom:12px}.editgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.notice{padding:10px;border-radius:9px;margin-bottom:12px}.ok{background:#f0fdf4}.err{background:#fef2f2}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:9px;border-bottom:1px solid #edf0f4;text-align:left;font-size:13px}@media(max-width:900px){.grid,.editgrid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">Communications</h1><div class="muted">Create, edit, disable and safely delete templates; review delivery logs.</div></div><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div>@if(session('success'))<div class="notice ok">{{ session('success') }}</div>@endif @if($errors->any())<div class="notice err"><ul style="margin:0;padding-left:18px">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<div class="grid"><div><div class="card"><h2 style="margin-top:0">Create Template</h2><form method="POST" action="{{ route('admin.communications.templates.store') }}">@csrf<div class="field"><label>Name<input name="name" required></label></div><div class="field"><label>Slug<input name="slug" required placeholder="fee-due-reminder"></label></div><div class="field"><label>Channel<select name="channel"><option value="whatsapp">WhatsApp</option><option value="sms">SMS</option><option value="email">Email</option></select></label></div><div class="field"><label>Subject<input name="subject"></label></div><div class="field"><label>Body<textarea name="body" rows="6" required></textarea></label></div><label><input style="width:auto" type="checkbox" name="status" value="1" checked> Active</label><br><button class="btn alt" style="margin-top:10px">Save Template</button></form></div></div><div><div class="card"><h2 style="margin-top:0">Templates</h2>@forelse($templates as $template)<div class="template"><div class="top" style="margin-bottom:8px"><div><strong>{{ $template->name }}</strong><div class="muted">{{ strtoupper($template->channel) }} · {{ $template->slug }} · Logs: {{ $template->logs_count }}</div></div><span>{{ $template->status?'Active':'Disabled' }}</span></div><form method="POST" action="{{ route('admin.communications.templates.update',$template) }}">@csrf @method('PATCH')<div class="editgrid"><input name="name" value="{{ $template->name }}" required><input name="slug" value="{{ $template->slug }}" required><select name="channel">@foreach(['whatsapp','sms','email'] as $channel)<option value="{{ $channel }}" @selected($template->channel===$channel)>{{ strtoupper($channel) }}</option>@endforeach</select><input name="subject" value="{{ $template->subject }}" placeholder="Subject"></div><textarea name="body" rows="4" required>{{ $template->body }}</textarea><div class="inline" style="margin-top:8px"><label><input style="width:auto" type="checkbox" name="status" value="1" @checked($template->status)> Active</label><button class="btn alt">Save Edit</button></div></form><form method="POST" action="{{ route('admin.communications.templates.destroy',$template) }}" style="margin-top:8px" onsubmit="return confirm('Delete this template? Templates with logs will be disabled instead.')">@csrf @method('DELETE')<button class="btn danger">Delete / Safe Disable</button></form></div>@empty<div class="muted">No templates yet.</div>@endforelse</div><div class="card"><h2 style="margin-top:0">Communication Log</h2><form method="GET" class="inline" style="margin-bottom:12px"><select name="channel" style="max-width:180px"><option value="">All channels</option>@foreach(['email','sms','whatsapp'] as $channel)<option value="{{ $channel }}" @selected(request('channel')===$channel)>{{ strtoupper($channel) }}</option>@endforeach</select><select name="status" style="max-width:180px"><option value="">All statuses</option>@foreach(['queued','sent','failed','skipped'] as $status)<option value="{{ $status }}" @selected(request('status')===$status)>{{ ucfirst($status) }}</option>@endforeach</select><button class="btn">Filter</button></form><div style="overflow:auto"><table class="table"><thead><tr><th>Date</th><th>Channel</th><th>Recipient</th><th>Template</th><th>Status</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at?->format('d M Y H:i') }}</td><td>{{ strtoupper($log->channel) }}</td><td>{{ str_contains((string)$log->recipient,'@') ? preg_replace('/(^.).*(@.*$)/','$1***$2',(string)$log->recipient) : '****'.substr(preg_replace('/\D+/','',(string)$log->recipient),-4) }}</td><td>{{ $log->template?->name ?? 'Manual' }}</td><td>{{ ucfirst($log->status) }}</td></tr>@empty<tr><td colspan="5" class="muted">No communication logs yet.</td></tr>@endforelse</tbody></table></div>{{ $logs->links() }}</div></div></div></div></body></html>